"""FAQ scientifique : v1, 20 cas, quatre domaines. Corrigé conservé côté serveur."""
VERSION = 'faq-2026-10-v1'
CATEGORIES = ['Métabolisme', 'Biomécanique', 'Nutrition', 'Compléments']


def q(id, category, title, question, options, correct, explanation, takeaway, source, url):
    return dict(id=str(id), category=category, title=title, question=question,
                options=options, correct=correct, explanation=explanation,
                takeaway=takeaway, source={'title': source, 'url': url})


QUESTIONS = [
q(1, 'Métabolisme', 'Brûler du gras… mais lequel ?',
  'Je réduis fortement les glucides et mon oxydation des lipides augmente. Cela prouve quoi sur la perte de ma graisse corporelle ?',
  ['Une perte supérieure dès que les lipides deviennent le carburant majoritaire.',
   'Une utilisation accrue des lipides, sans preuve de bilan lipidique plus négatif.',
   'Une perte identique chez chacun si la proportion de lipides oxydés est identique.',
   'Une perte supérieure à calories égales, indépendamment des lipides consommés.'], 1,
  'Oxydation et perte nette ne sont pas synonymes. Tu peux brûler davantage de lipides parce que tu en manges davantage. Le bilan lipidique dépend aussi de leur entrée dans l’organisme. Dans l’essai contrôlé de Hall, la restriction glucidique a augmenté l’oxydation des lipides, mais la restriction des lipides a produit davantage de perte de graisse sur la courte période étudiée. Ce résultat ne désigne pas un régime universellement supérieur à long terme.',
  'Regarde l’évolution de la composition corporelle et l’alimentation réelle, pas seulement le carburant utilisé.',
  'Hall et al., Cell Metabolism, 2015', 'https://pubmed.ncbi.nlm.nih.gov/26278052/'),
q(2, 'Métabolisme', 'Un chiffre qui dépasse 1',
  'Pendant un effort intense non stabilisé, mon RER, le rapport CO₂ expiré / O₂ consommé, dépasse 1. Peut-on en déduire précisément la part de glucides brûlés ?',
  ['Oui, cela signifie que les protéines remplacent complètement les lipides.',
   'Oui, en extrapolant linéairement les tables établies au repos.',
   'Oui, le CO₂ expiré provient alors exclusivement de l’oxydation du glucose.',
   'Non, le tamponnement et la dynamique ventilatoire perturbent cette estimation.'], 3,
  'Lors d’un effort intense, une partie du CO₂ expiré provient du tamponnement des ions H⁺ par les bicarbonates. Les variations de ventilation et des réserves de CO₂ comptent aussi. Le RER mesuré à la bouche n’est donc pas toujours le quotient respiratoire des tissus. Les calculs de substrats demandent des conditions adaptées, notamment un état relativement stabilisé. Un RER supérieur à 1 n’est pas un pourcentage de glucides supérieur à 100.',
  'Un indicateur n’est interprétable que dans les conditions pour lesquelles son modèle est valable.',
  'Beaver, Wasserman et Whipp, Journal of Applied Physiology, 1986', 'https://pubmed.ncbi.nlm.nih.gov/3087938/'),
q(3, 'Métabolisme', 'Métabolisme cassé ou adaptation ?',
  'Après une perte de poids, ma dépense de repos baisse. Quelle observation soutiendrait spécifiquement une thermogenèse adaptative ?',
  ['Une baisse supérieure à celle attendue compte tenu de la nouvelle composition corporelle.',
   'Une baisse qui correspond exactement à la diminution des tissus métaboliquement actifs.',
   'Une baisse affichée par une montre après une seule nuit plus courte.',
   'Une baisse du poids sans changement mesuré de la dépense énergétique.'], 0,
  'Un corps plus léger et une moindre masse de tissus actifs peuvent expliquer une partie de la baisse de dépense. La thermogenèse adaptative correspond à une diminution supplémentaire par rapport à ce qui est attendu après ces changements, avec les limites des modèles et des mesures. Une montre ou un plateau isolé ne suffit pas à la démontrer. Adaptation ne signifie ni métabolisme définitivement cassé ni impossibilité de progresser.',
  'Sépare la baisse attendue, l’adaptation possible et l’incertitude de mesure avant de conclure.',
  'Rosenbaum et Leibel, Adaptive thermogenesis in humans, 2010', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC3673773/'),
q(4, 'Métabolisme', 'Le sport ne raconte pas toute la journée',
  'Je fais davantage de cardio, mais je passe ensuite bien plus de temps assis. Pourquoi les calories de la séance ne représentent-elles pas forcément le supplément de dépense sur la journée ?',
  ['Le cardio transforme toujours les calories dépensées en calories stockées.',
   'L’effet thermique des repas annule obligatoirement toute séance ajoutée.',
   'Une baisse de l’activité spontanée peut compenser une partie de la dépense ajoutée.',
   'La dépense hors entraînement est une constante, fixée uniquement par le poids.'], 2,
  'Le NEAT désigne les mouvements hors exercice structuré : déplacements, maintien de posture, petits gestes et autres activités quotidiennes. Il varie entre personnes et selon les conditions. Si tu bouges moins après avoir ajouté une séance, la dépense totale ne monte pas nécessairement du montant affiché pour cette séance. Les travaux de Levine montrent l’importance et la variabilité du NEAT, sans prouver qu’une compensation précise existe chez chaque personne après le cardio.',
  'Compare aussi l’activité du reste de la journée ; une séance n’est pas un bilan énergétique complet.',
  'Levine et al., Science, 1999', 'https://pubmed.ncbi.nlm.nih.gov/9880251/'),
q(5, 'Métabolisme', 'Synthétiser ne veut pas toujours dire grossir',
  'Après ma première séance très dommageable, la synthèse de protéines musculaires grimpe fortement. Puis-je utiliser ce pic pour prédire mon hypertrophie future ?',
  ['Oui, le pic initial classe précisément les futurs gains de muscle.',
   'Non, une partie de cette réponse accompagne la réparation des dommages.',
   'Oui, à condition que les courbatures durent plus longtemps que la séance.',
   'Non, parce que la synthèse protéique ne participe jamais à l’hypertrophie.'], 1,
  'La synthèse de protéines sert aussi au renouvellement et à la réparation. Dans les travaux de Damas, la réponse initiale, associée aux dommages les plus importants, n’était pas reliée à l’hypertrophie comme l’étaient les réponses après adaptation à l’entraînement. La synthèse reste importante pour le muscle, mais son rôle et son interprétation dépendent du contexte. Chercher davantage de dommages n’est donc pas une stratégie fiable pour chercher davantage de croissance.',
  'Juge la progression sur plusieurs semaines, pas sur les courbatures ou un pic biologique isolé.',
  'Damas et al., Journal of Physiology, 2016', 'https://pubmed.ncbi.nlm.nih.gov/27219125/'),
q(6, 'Biomécanique', 'Pourquoi la position de hanche compte',
  'À angle de genou identique, passer du leg curl couché au leg curl assis change quoi pour les ischio-jambiers biarticulaires ?',
  ['La flexion de hanche les place généralement à une longueur plus importante.',
   'La flexion de hanche raccourcit tous les ischio-jambiers de façon identique.',
   'Leur longueur dépend uniquement du genou, donc rien ne change.',
   'Le changement concerne uniquement le chef court du biceps fémoral.'], 0,
  'Les ischio-jambiers biarticulaires traversent la hanche et le genou. Fléchir la hanche les allonge, à angle de genou donné. Le chef court du biceps fémoral ne traverse pas la hanche : il ne suit pas cette logique. Dans l’essai de Maeo, le leg curl assis a davantage fait croître les muscles biarticulaires. Cela ne rend pas toutes les machines équivalentes ni une position automatiquement adaptée à chaque personne.',
  'Pour un muscle biarticulaire, regarde les deux articulations, pas seulement celle qui bouge.',
  'Maeo et al., Medicine & Science in Sports & Exercise, 2021', 'https://pubmed.ncbi.nlm.nih.gov/33009197/'),
q(7, 'Biomécanique', 'Moins lourd, davantage de muscle ?',
  'Je soulève moins lourd en extension de triceps au-dessus de la tête qu’avec le bras le long du corps. Cela suffit-il à conclure que la première version stimule moins le triceps ?',
  ['Oui, le nombre de kilos détermine directement la croissance de chaque chef.',
   'Oui, si l’amplitude du coude est identique entre les deux positions.',
   'Non, toute position inconfortable augmente nécessairement l’hypertrophie.',
   'Non, la position d’épaule et la longueur musculaire changent la comparaison.'], 3,
  'Le chef long du triceps traverse aussi l’épaule. La position au-dessus de la tête l’allonge davantage. Dans l’essai de Maeo, cette position a produit davantage d’hypertrophie malgré des charges absolues plus faibles. Ce n’est pas une garantie individuelle ni une consigne d’ignorer une épaule douloureuse. Les kilos affichés ne suffisent pas à comparer deux exercices dont la géométrie et les conditions musculaires diffèrent.',
  'Compare des conditions mécaniques et une progression maîtrisée, pas seulement deux piles de poids.',
  'Maeo et al., European Journal of Sport Science, 2023', 'https://pubmed.ncbi.nlm.nih.gov/35819335/'),
q(8, 'Biomécanique', 'Le piège du bras de levier',
  'Cas statique simplifié : une force de 200 N agit à 0,30 m perpendiculairement à l’articulation. On passe à 300 N mais à 0,15 m. Que devient le moment externe ?',
  ['Il augmente de moitié, parce que la force augmente de moitié.',
   'Il reste identique, parce que force et distance se compensent exactement.',
   'Il passe de 60 à 45 N·m ; la force musculaire interne reste à analyser séparément.',
   'Il passe de 60 à 90 N·m ; le bras de levier est sans effet.'], 2,
  'Le moment externe est la force multipliée par sa distance perpendiculaire à l’axe : 200 × 0,30 = 60 N·m, puis 300 × 0,15 = 45 N·m. La force augmente, mais son levier diminue davantage. Pour déduire les forces musculaires internes, il faudrait aussi considérer les bras de levier internes, les autres forces et la cocontraction. Le calcul décrit ce cas statique, pas toute une répétition dynamique.',
  'Une charge plus lourde peut produire un moment externe plus faible si sa ligne d’action change.',
  'OpenStax, University Physics, Torque', 'https://openstax.org/books/university-physics-volume-1/pages/10-6-torque'),
q(9, 'Biomécanique', 'L’EMG n’est pas une boule de cristal',
  'Une vidéo classe les exercices selon leur amplitude EMG de surface et annonce le meilleur pour l’hypertrophie. Quelle limite remet le plus directement en cause ce classement ?',
  ['L’amplitude EMG ne constitue pas une mesure directe des gains musculaires futurs.',
   'Un signal EMG élevé indique nécessairement que le muscle ne travaille pas.',
   'L’EMG mesure uniquement le nombre de répétitions réalisées dans la série.',
   'L’EMG peut prédire l’hypertrophie sans tenir compte des positions ni des électrodes.'], 0,
  'L’EMG renseigne sur une activité électrique enregistrée dans certaines conditions. Le signal varie notamment avec la géométrie, les électrodes, la normalisation et les propriétés du tissu. Il n’est ni une mesure directe de la force musculaire, ni une validation des gains à long terme. Une comparaison aiguë intéressante ne remplace pas une étude d’entraînement. Cela ne rend pas l’outil inutile : cela limite les conclusions qu’on peut en tirer.',
  'Demande ce qui a réellement été mesuré avant d’accepter un classement d’exercices.',
  'Vigotsky et al., Frontiers in Physiology, 2018', 'https://pubmed.ncbi.nlm.nih.gov/29354060/'),
q(10, 'Biomécanique', 'Plus de kilos, moins d’amplitude',
  'Je charge davantage mon squat mais je réduis beaucoup sa profondeur. Puis-je affirmer que la demande relative sur les extenseurs du genou est forcément supérieure ?',
  ['Oui, puisque la charge est le seul déterminant de l’effort relatif.',
   'Oui, toute amplitude raccourcie déplace automatiquement l’effort vers les quadriceps.',
   'Non, une amplitude plus courte supprime toute demande sur le genou.',
   'Non, profondeur, angles et moments articulaires changent aussi la demande.'], 3,
  'L’effort relatif rapporte la demande mécanique à la capacité de produire un moment à l’angle considéré. Charge et profondeur ne modifient pas toutes les articulations de la même façon. Dans l’étude de Bryanton, la profondeur influençait nettement l’effort relatif des extenseurs du genou, tandis que les effets de charge différaient selon les groupes musculaires. Ce petit essai ne permet pas de déduire ton recrutement précis à partir du seul poids sur la barre.',
  'Une progression ne se lit correctement que si tu notes aussi l’amplitude et l’exécution.',
  'Bryanton et al., Journal of Strength and Conditioning Research, 2012', 'https://pubmed.ncbi.nlm.nih.gov/22797000/'),
q(11, 'Nutrition', 'L’insuline ne remplace pas les acides aminés',
  'Après une prise de protéines suffisante dans une expérience, ajouter des glucides et augmenter l’insuline garantit-il une synthèse protéique musculaire supérieure ?',
  ['Oui, la synthèse augmente proportionnellement à chaque hausse d’insuline.',
   'Non, l’ajout de glucides ne garantit pas un supplément de synthèse dans ce contexte.',
   'Oui, les glucides deviennent directement des acides aminés essentiels dans le muscle.',
   'Non, parce que l’insuline ne joue aucun rôle dans le métabolisme des protéines.'], 1,
  'L’insuline et les acides aminés n’ont pas le même rôle. Dans l’expérience de Gorissen, ajouter des glucides à la protéine a retardé l’apparition des acides aminés alimentaires sans augmenter l’accrétion protéique musculaire postprandiale mesurée. C’est un résultat aigu chez des hommes étudiés dans un protocole précis. Il ne dit pas que les glucides sont inutiles pour l’entraînement, le glycogène ou les apports énergétiques.',
  'Ne confonds pas une hausse hormonale avec un bénéfice musculaire supplémentaire démontré.',
  'Gorissen et al., Journal of Clinical Endocrinology & Metabolism, 2014', 'https://pubmed.ncbi.nlm.nih.gov/24628553/'),
q(12, 'Nutrition', 'Une étude aiguë n’est pas une règle universelle',
  'Une étude trouve une meilleure synthèse protéique sur 12 heures avec une répartition intermédiaire des prises. Quelle conclusion est la plus défendable ?',
  ['La quantité optimale par repas est désormais identique pour tous les gabarits.',
   'La répartition observée garantit la meilleure hypertrophie sur un an.',
   'La répartition peut compter, mais le protocole aigu ne fixe pas une dose universelle.',
   'L’apport protéique total devient sans importance dès que les prises sont régulières.'], 2,
  'Areta a comparé différentes distributions d’une même quantité de protéines chez de jeunes hommes entraînés, après une séance, sur 12 heures. Une distribution intermédiaire a mieux stimulé la synthèse dans ce protocole. La population, la quantité totale, la source protéique et la fenêtre d’observation limitent l’extrapolation. Cela invite à réfléchir à la répartition, sans transformer un résultat aigu en plafond absolu par repas ni en garantie de croissance à long terme.',
  'Pour appliquer une étude, garde ensemble sa population, son protocole et ce qu’elle mesure.',
  'Areta et al., Journal of Physiology, 2013', 'https://doi.org/10.1113/jphysiol.2012.244897'),
q(13, 'Nutrition', 'Le repas change l’absorption',
  'Je compte le fer de mon repas végétal et je prends systématiquement un café avec. Pourquoi les milligrammes ingérés ne racontent-ils pas toute l’histoire ?',
  ['Le café peut réduire l’absorption du fer non héminique ; quantité et absorption diffèrent.',
   'La caféine transforme nécessairement le fer non héminique en fer héminique.',
   'Tout le fer d’un repas est absorbé, quelle que soit sa composition.',
   'Un café avec le repas garantit une meilleure absorption des minéraux.'], 0,
  'Le fer non héminique est sensible à la composition du repas. Les études isotopiques de Morck montrent que le café pris avec le repas peut réduire son absorption. La quantité affichée n’est donc pas la quantité effectivement absorbée. Cette expérience ne signifie pas que toute personne buvant du café est carencée, ni qu’il faut ajouter du fer sans raison. Le statut réel et l’ensemble de l’alimentation restent importants.',
  'Ne juge pas la disponibilité d’un micronutriment uniquement sur sa ligne dans un tableau alimentaire.',
  'Morck, Lynch et Cook, American Journal of Clinical Nutrition, 1983', 'https://pubmed.ncbi.nlm.nih.gov/6402915/'),
q(14, 'Nutrition', 'Poids stable, énergie suffisante ?',
  'Une sportive garde un poids stable, mais augmente beaucoup son entraînement et voit son cycle se perturber. Le poids stable permet-il d’exclure une faible disponibilité énergétique ?',
  ['Oui, la stabilité du poids prouve que chaque fonction reçoit assez d’énergie.',
   'Oui, si sa masse grasse paraît faible mais reste visuellement identique.',
   'Non, une perturbation du cycle prouve à elle seule une carence en fer.',
   'Non, la disponibilité énergétique ne se résume pas à la stabilité du poids.'], 3,
  'La disponibilité énergétique considère l’énergie restant après la dépense d’exercice, relativement à la masse maigre. Des adaptations de dépense peuvent contribuer à stabiliser le poids sans garantir une énergie suffisante pour toutes les fonctions. L’essai de Loucks a montré que manipuler cette disponibilité pouvait perturber la pulsativité de LH. Un cycle perturbé a plusieurs causes possibles : ce signe justifie d’examiner apports, entraînement et contexte, pas de poser un diagnostic sur le quiz.',
  'Un poids stable n’est pas, à lui seul, un certificat de récupération ou de fonctionnement hormonal.',
  'Loucks et Thuma, Journal of Clinical Endocrinology & Metabolism, 2003', 'https://pubmed.ncbi.nlm.nih.gov/12519869/'),
q(15, 'Nutrition', 'Un surplus riche en protéines',
  'Dans un essai de suralimentation contrôlée, davantage de protéines peut modifier la masse maigre et la dépense. Cela implique-t-il que les protéines rendent tout surplus inoffensif pour la masse grasse ?',
  ['Oui, dès que les protéines augmentent, la prise de graisse est bloquée.',
   'Non, une amélioration de la masse maigre n’annule pas nécessairement le gain de graisse.',
   'Oui, la dépense augmente obligatoirement jusqu’à absorber tout l’excédent.',
   'Non, parce que les protéines empêchent toute augmentation de masse maigre.'], 1,
  'Dans l’essai contrôlé de Bray, les groupes avec différents apports protéiques ont gagné de la graisse de façon similaire, alors que la masse maigre et la dépense différaient. Les protéines ont des effets spécifiques, mais ce n’est pas une permission de manger sans limite. Ce protocole de suralimentation n’était pas un programme personnalisé de musculation. Il illustre surtout pourquoi masse totale, masse maigre et masse grasse doivent être distinguées.',
  'Un bon apport protéique n’exonère pas de piloter l’énergie totale et la composition corporelle.',
  'Bray et al., JAMA, 2012', 'https://pubmed.ncbi.nlm.nih.gov/22215165/'),
q(16, 'Compléments', 'Créatinine : interpréter, pas paniquer',
  'Une personne prend de la créatine et sa créatinine sanguine augmente légèrement. Quelle conclusion est justifiée par ce seul résultat ?',
  ['La filtration rénale est nécessairement altérée dans les mêmes proportions.',
   'Tout résultat rénal devient inutilisable et peut être ignoré.',
   'Aucune conclusion définitive : contexte et autres marqueurs rénaux sont nécessaires.',
   'Une hausse prouve que la créatine protège contre toutes les maladies rénales.'], 2,
  'La créatinine est liée au métabolisme de la créatine et à la masse musculaire, pas seulement à la filtration rénale. Une variation isolée ne permet pas d’affirmer une lésion ni de l’exclure. Dans un essai chez des pratiquants sains, la filtration directement mesurée n’a pas diminué après supplémentation. Cela ne couvre pas toutes les situations ni les maladies rénales : une interprétation sérieuse garde le contexte, la tendance et les marqueurs complémentaires.',
  'Un biomarqueur influencé par plusieurs facteurs ne constitue pas à lui seul un diagnostic.',
  'Lugaresi et al., Journal of the International Society of Sports Nutrition, 2013', 'https://pubmed.ncbi.nlm.nih.gov/23680457/'),
q(17, 'Compléments', 'Les picotements ne sont pas le mécanisme',
  'Je ressens des picotements après de la bêta-alanine. Est-ce une preuve que ma capacité à tamponner l’acidité musculaire a immédiatement augmenté ?',
  ['Non, la sensation aiguë ne mesure pas l’augmentation progressive de la carnosine musculaire.',
   'Oui, les picotements sont une mesure directe de la carnosine du muscle.',
   'Oui, plus ils sont forts, plus la performance du jour est garantie.',
   'Non, parce que la carnosine ne participe à aucun tamponnement.'], 0,
  'La bêta-alanine est un précurseur de la carnosine, qui participe au tamponnement dans le muscle. Les essais ont étudié une augmentation de carnosine après des semaines de supplémentation, pas une validation par la sensation cutanée juste après une prise. Les picotements ne sont pas un indicateur de résultat sportif et ne justifient pas de chercher une prise plus importante. L’intérêt dépend aussi du type d’effort étudié.',
  'Une sensation perceptible peut être un effet secondaire, pas une preuve d’efficacité.',
  'Hill et al., Amino Acids, 2007', 'https://pubmed.ncbi.nlm.nih.gov/16868650/'),
q(18, 'Compléments', 'Le milligramme qui manque sur la face avant',
  'Deux produits affichent des quantités très différentes de citrate ou de bisglycinate de magnésium. Quelle information faut-il d’abord comparer pour connaître la quantité de magnésium apportée ?',
  ['Le poids total des gélules, puisqu’il correspond au magnésium absorbé.',
   'La quantité de sel annoncée, supposée être entièrement du magnésium.',
   'Le nombre de mentions du magnésium sur la face avant de la boîte.',
   'Le magnésium élémentaire par portion, puis la forme et la tolérance.'], 3,
  'Le sel comprend le magnésium et les autres composants de la molécule : son poids n’est pas celui du magnésium élémentaire. La fiche NIH précise que l’étiquetage de la quantité de magnésium concerne l’élément, non le composé entier. La portion compte aussi. Ensuite viennent la forme, l’absorption et la tolérance digestive. Comparer seulement le gros chiffre de la face avant peut donc conduire à une conclusion fausse.',
  'Lis la quantité élémentaire et la portion avant de comparer deux compléments.',
  'NIH Office of Dietary Supplements, Magnesium', 'https://ods.od.nih.gov/factsheets/Magnesium-HealthProfessional/'),
q(19, 'Compléments', 'Vitamine D : quel marqueur ?',
  'Un dosage de 1,25-dihydroxyvitamine D est normal. Pourquoi cela ne suffit-il pas à conclure que le statut en vitamine D est satisfaisant ?',
  ['Parce que la forme active est toujours absente chez une personne saine.',
   'Parce que la 25(OH)D est l’indicateur habituel du statut ; la forme active est fortement régulée.',
   'Parce que seule la couleur de peau permet d’évaluer le statut individuel.',
   'Parce que les deux dosages sont identiques et doivent être additionnés.'], 1,
  'La 25(OH)D est l’indicateur habituellement utilisé pour le statut en vitamine D. La 1,25(OH)₂D, forme active, est plus brièvement présente dans le sang et fortement régulée, notamment par la parathormone, le calcium et le phosphate. Elle peut donc rester normale alors que les réserves ne le sont pas. Cela n’impose pas un dépistage systématique chez toute personne saine ni une supplémentation importante sans raison.',
  'Un marqueur actif et régulé ne reflète pas nécessairement les réserves disponibles.',
  'NIH Office of Dietary Supplements, Vitamin D', 'https://ods.od.nih.gov/factsheets/VitaminD-HealthProfessional/'),
q(20, 'Compléments', 'Antioxydants : plus n’est pas toujours mieux',
  'Un essai de vitamines C et E à doses élevées atténue certains marqueurs d’adaptation à l’endurance, sans différence nette de performance. Quelle conclusion respecte ces résultats ?',
  ['Tous les fruits et légumes doivent être supprimés autour du sport.',
   'Le changement d’un marqueur prouve une baisse identique de chaque performance.',
   'Ces fortes doses ne sont pas automatiquement bénéfiques ; marqueurs et performance restent distincts.',
   'Tout complément antioxydant garantit une adaptation supérieure à l’entraînement.'], 2,
  'Les espèces réactives participent aussi aux signaux d’adaptation : leur présence n’est pas uniquement un dommage à effacer. Dans l’essai de Paulsen, de fortes doses de vitamines C et E ont atténué des marqueurs de biogenèse mitochondriale, sans différence nette des progrès de VO₂max ou de course entre groupes. Il faut garder cette nuance. Cela ne condamne pas les fruits, les légumes ou un apport alimentaire normal.',
  'Un mécanisme séduisant et une dose plus élevée ne garantissent pas un bénéfice réel.',
  'Paulsen et al., Journal of Physiology, 2014', 'https://pubmed.ncbi.nlm.nih.gov/24492839/'),
]
